USE atp;

SELECT PlayerName from 	oponents 
WHERE PlayerName NOT IN (SELECT DISTINCT PlayerName FROM players);

CREATE TABLE `countries` (
  `Name` varchar(44) DEFAULT NULL,
  `Code` varchar(2) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Extraindo dados da tabela `countries`
--

COMMIT;

ALTER TABLE `countries` ADD PRIMARY KEY(`Code`); 

CREATE TABLE country_location_match (
    location VARCHAR(100) PRIMARY KEY,
    extracted_country VARCHAR(100) DEFAULT NULL,
    country_code VARCHAR(2) DEFAULT NULL,
    FOREIGN KEY (country_code) REFERENCES countries(code)
);

	SELECT DISTINCT t.Location, TRIM(SUBSTRING_INDEX(t.Location, ',', -1)) AS extracted_country 
	FROM Tournaments AS t 
	WHERE t.Location IS NOT NULL AND t.Location LIKE '%,%' 
UNION 
	SELECT DISTINCT p.Born, TRIM(SUBSTRING_INDEX(p.Born, ',', -1)) AS extracted_country 
	FROM players AS p 
	WHERE p.Born IS NOT NULL AND p.Born LIKE '%,%'; 
	
SELECT DISTINCT t.Location, t.Location
FROM Tournaments AS t
WHERE t.Location IS NOT NULL AND t.Location NOT LIKE '%,%'
UNION
SELECT DISTINCT p.Born, p.Born
FROM players AS p
WHERE p.Born IS NOT NULL AND p.born NOT LIKE '%,%';

UPDATE country_location_match AS clm
JOIN Countries AS c ON clm.extracted_country = c.Name
SET clm.country_code = c.Code
WHERE clm.country_code IS NULL;

