ALTER TABLE `players` ADD `country_code` VARCHAR(2) NULL DEFAULT NULL AFTER `LinkPlayer`; 
ALTER TABLE `players` ADD CONSTRAINT `fk_playercountry_countrycode` FOREIGN KEY (`country_code`) REFERENCES `countries`(`Code`) ON DELETE SET NULL ON UPDATE SET NULL; 

UPDATE players p
JOIN country_location_match clm ON p.Born = clm.location
SET p.country_code = clm.country_code;

ALTER TABLE `tournaments` ADD `country_code` VARCHAR(2) NULL DEFAULT NULL AFTER `Prize`;
ALTER TABLE `tournaments` ADD CONSTRAINT `fk_tournamentcountry_countrycode` FOREIGN KEY (`country_code`) REFERENCES `countries`(`Code`) ON DELETE SET NULL ON UPDATE SET NULL;

UPDATE tournaments t
JOIN country_location_match clm ON t.Location = clm.Location
SET t.country_code = clm.country_code;

ALTER TABLE `unique_matches` ADD `PlayerID` INT NULL DEFAULT NULL AFTER `Score`, ADD `OponentID` INT NULL DEFAULT NULL AFTER `PlayerID`, ADD `TournamentID` INT NULL DEFAULT NULL AFTER `OponentID`; 
ALTER TABLE `unique_matches` ADD CONSTRAINT `fk_matchplayer_playerid` FOREIGN KEY (`PlayerID`) REFERENCES `players`(`id`) ON DELETE RESTRICT ON UPDATE RESTRICT; 
ALTER TABLE `unique_matches` ADD CONSTRAINT `fk_matchoponent_playerid` FOREIGN KEY (`OponentID`) REFERENCES `players`(`id`) ON DELETE RESTRICT ON UPDATE RESTRICT; 
ALTER TABLE `unique_matches` ADD CONSTRAINT `fk_matchtournament_tournamentid` FOREIGN KEY (`TournamentID`) REFERENCES `tournaments`(`id`) ON DELETE RESTRICT ON UPDATE RESTRICT; 


