CREATE TABLE `worldcities_small` (
  `city` varchar(49) DEFAULT NULL,
  `city_ascii` varchar(49) DEFAULT NULL,
  `country` varchar(45) DEFAULT NULL,
  `iso2` varchar(2) DEFAULT NULL,
  `iso3` varchar(3) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Extraindo dados da tabela `worldcities_small`
--

COMMIT;

ALTER TABLE `worldcities_small` ADD `id` INT NOT NULL AUTO_INCREMENT FIRST, ADD PRIMARY KEY (`id`); 

DELETE FROM worldcities_small w
WHERE NOT EXISTS (
    SELECT 1 
    FROM countries c 
    WHERE c.code = w.iso2
);

ALTER TABLE `worldcities_small` ADD CONSTRAINT `fk_worldcitiesiso2_countrycode` FOREIGN KEY (`iso2`) REFERENCES `countries`(`Code`) ON DELETE RESTRICT ON UPDATE RESTRICT; 

UPDATE country_location_match clm
JOIN worldcities_small wc ON wc.city = clm.location
SET clm.country_code = wc.iso2
WHERE country_code IS NULL;

UPDATE country_location_match clm
JOIN worldcities_small wc ON wc.city = clm.extracted_country
SET clm.country_code = wc.iso2
WHERE country_code IS NULL;

ALTER TABLE country_location_match ADD COLUMN city VARCHAR(255);
UPDATE country_location_match
SET city = TRIM(SUBSTRING_INDEX(location, ',', 1));

UPDATE country_location_match AS clm
JOIN Countries AS c 
ON clm.extracted_country = c.code
SET clm.country_code = c.Code
WHERE clm.country_code IS NULL;

UPDATE players p
